// W3 · Route — разбор обновления от Telegram Trigger (callback_query и message).
// Нода: Code, режим «Run Once for All Items».
// Выход: один item или [] (не наше — игнорируем):
//   { action: 'choice', id, choice, queryId, chatId, messageId, panel } — нажата кнопка решения.
//      callback_data = v:<id строки>:<apply|maybe|skip|earlier|edit> — на карточке; messageId — id карточки, panel = null;
//      callback_data = pv:<id>:<choice>:<tab>:<page> — в карточке на панели меню (W7; score — «🤖 На оценку» у отсеянной):
//      panel = { messageId, tab, page } — панель перерисуется после решения.
//   { action: 'letter', id, op, queryId, chatId, messageId } — кнопка под письмом (W5):
//      callback_data = l:<id строки>:<redo|sent|unsent|cancel>; messageId — сообщение с письмом;
//      cancel — «↩️ Отменить отклик» (14.10.2026): вакансия снова ждёт решения.
//   { action: 'robot', op, id, queryId, chatId, messageId, text, promptId, userMessageId } — робот-отклик (этап 6) →
//      W9 Robot: l:<id>:robot — 🚀 (op enqueue), l:<id>:stop — ⛔ (op stop), rb:go и команда /go — ▶️ после блока
//      (op resume), ответ на фото капчи (подпись начинается с ROBOT_PROMPTS.captcha) — op captcha, text — ответ.
//   { action: 'reply', replyTo, messageId, chatId, text } — ответ (reply) на вопрос «почему?», карточку или письмо.
//   { action: 'panel', view, tab, page, id, chatId, queryId, messageId, userMessageId } — меню бота → W7 Bot menu:
//      кнопки под полем ввода («📋 Вакансии», «📊 Статистика», «🤖 Автоотклик», «⚙️ Настройки»), команды /start, /menu,
//      /vacancies, /stats, /auto, /settings, /v<id> и кнопки панели (callback_data p:…, s:…, sc:…, sn, au:…).
//      view = list | stats | start | open | noop | sync | settings | auto;
//      auto (6.1c): панель автоотклика; change = { name: 'apply.auto', set } — ▶️ Запустить / ⏹ Остановить (au:on|off);
//      settings: section — раздел, change = { name, toggle? } — следующее значение настройки или правило фильтра,
//      collectNow — собрать сейчас, ask — вопрос со списком, input = { name, text } — ответ на него (promptId — вопрос),
//      unban — убрать компанию из чёрного списка, id — компания для подтверждения (/bl<id>);
//      resume = true — список там, где был (p:n — «📋 К вакансиям» под письмом: новая панель, не правка письма);
//      messageId — панель, где нажали кнопку (правим её); userMessageId — сообщение пользователя (удалить).
//   { action: 'profile', op, field, value, chatId, queryId, messageId, userMessageId, promptId, text, file, username } —
//      профиль (W11, 13.10.2026): документ в чате (op pdf | not_pdf, file = { id, name, size }), кнопки pf:* и ответы
//      на вопросы профиля (PROFILE_PROMPTS, op input).
//      Несколько резюме (docs/resumes.md): кнопки rm:* — op rm, field — действие, value — id резюме[:флаг];
//      импорт с hh — rm:imp (field imp) и rm:i:<сессия>:<действие> (field i, value «сессия:действие»).
//   { action: 'resume', data, op, field, text, chatId, queryId, messageId, userMessageId, promptId } — рекомендации по
//      резюме (W13, 15.10.2026): кнопки rs: ru: rq: rp: rr: rc: rk: rx: re: (data — как есть, разбирает W13 «Job») и ответы на вопросы
//      RESUME_PROMPTS (op input).
// Чужие чаты отсекает сам Telegram Trigger (Restrict to Chat IDs = TG_CHAT_ID); здесь — вторая проверка.

// Меню бота: кнопки под полем ввода и вкладки списка вакансий (решения пользователя 07.10.2026).
// Общий код W3 «Route» и W7 «Render»: строка «// @include n8n/shared/menu.js».
//
// callback_data кнопок панели (Telegram — не длиннее 64 байт):
//   p:l:<tab>:<page>  — список: вкладка и страница;   p:s — статистика;   p:x — неактивная кнопка
//   p:n — новая панель со списком там, где был (кнопка «📋 К вакансиям» под отправленным письмом)
//   pv:<id>:<apply|maybe|skip|earlier|edit>:<tab>:<page> — решение в карточке на панели: W3 правит исходную карточку
//   в ленте, потом W7 перерисовывает панель. <tab>:<page> — куда вернёт «⬅️ К списку».
//   Настройки (⚙️, 07.10.2026): s:<раздел> — открыть раздел (root | collect | search | filter | rules | blacklist | llm);
//   sc:<имя настройки> — следующее значение по кругу (n8n/shared/settings.js); sn — «🔄 Собрать сейчас»;
//   st:<правило> — включить или выключить правило фильтра; sw:<имя> — вопрос со списком (ответ — сообщением);
//   bld:<id> — убрать компанию из чёрного списка (после /bl<id> и подтверждения).
//   Карточка: v:<id>:ban и pv:<id>:ban:<tab>:<page> — «🚫 В ЧС»: компания в чёрный список, вакансия — ❌.
//   Робот (этап 6): l:<id>:robot — 🚀 под письмом, l:<id>:stop — ⛔ из очереди, rb:go и /go — ▶️ продолжить после
//   блока; ответ на фото капчи (подпись начинается с ROBOT_PROMPTS.captcha) — текст капчи → W9.
//   Автоотклик (6.1c, 20.10.2026): кнопка «🤖 Автоотклик» под полем ввода и /auto — панель; au:on — ▶️ Запустить,
//   au:off — ⏹ Остановить (значение явное: двойное нажатие не переключит обратно), au:r — 🔄 Обновить.
//   Профиль (W11, 13.10.2026): pf:view — панель профиля (⚙️ → 👤); pf:ok — ✅ шага онбординга; pf:e:<поле> — вопрос
//   (ForceReply); pf:g:<m|f> — «делал / делала»; pf:tz:<IANA> — часовой пояс; pf:new:<all|text|no> — новое резюме
//   при готовом профиле; pf:yes / pf:no — сохранить или отменить правку. Документ PDF в чате — резюме → W11.
//   Рекомендации по резюме (W13, 15.10.2026, docs/recommendations.md): rs:view — панель (⚙️ → 💡); rs:up — Upgrade;
//   rs:file — резюме файлом; rs:undo[:y] — откат; ru:<sid>:<y|e|n> — план Upgrade; rq:<sid>:… — вопросы;
//   rp:<sid>:<правка>:<y|r|a|e|n> — правка; rr:<sid> — повторить запрос к нейросети. Разделы резюме (часть D):
//   rc:go[:n] — разложить резюме (n — без hh); rc:<sid>:<hh|nohh|x> — прочитать hh ещё раз, без hh, отмена;
//   rc:<sid>:<n>:<b|h|a|k> — раздел: как в боте, с hh, добавить место с hh, пропустить; rk:view — ключевые навыки hh;
//   rk:<sid>:<i> / p<стр> / d / x — галочка, страница, готово, отмена; rx:view / rx:up — опыт работы, улучшить опыт.
//   Выгрузка на hh: re:go — сравнить с hh; re:<sid>:<n>:<p|k|h> — раздел: на hh, не трогать, взять с hh в бота;
//   re:<sid>:<dry|live|x> — сухой прогон, записать на hh, отмена.
//   <sid> — сессия правки: старые кнопки не сработают. Разбирает W13 «Job», W3 только передаёт.
//   Несколько резюме (docs/resumes.md): rm:list — список (⚙️ → 📄); rm:o:<id> — карточка резюме; rm:on:<id>[:l] и
//   rm:off:<id>[:l] — включить и выключить поиск (l — вернуться к списку); rm:new — новое резюме (PDF или текст);
//   rm:ren:<id> — название; rm:clone:<id> — копия; rm:del:<id>[:y] — удалить (y — подтверждено); rm:txt:<id> — новый
//   текст (PDF). pf:new:add — PDF как новое резюме. <id> — r1 (основное) … r5. Разбирает W11 «Step».
//   Импорт с hh: rm:imp — список резюме hh (читает робот); rm:i:<сессия>:<n> — галочка у n-го резюме, :b — «это основное»,
//   :go — импортировать отмеченные, :next / :retry / :skip — дальше, ещё раз, пропустить, :x — хватит.

// Кнопки под полем ввода: Telegram присылает их текст обычным сообщением
const MENU = { list: '📋 Вакансии', stats: '📊 Статистика', auto: '🤖 Автоотклик', settings: '⚙️ Настройки' };

// Вопросы ⚙️ со списком (ForceReply): ответ W3 «Route» узнаёт по началу текста вопроса
const SETTING_PROMPTS = {
  'search.anywhere': '✏️ Поиск — слова везде в тексте',
  'search.in_name': '✏️ Поиск — слова в названии',
  'filter.stop_words': '✏️ Фильтр — стоп-слова в названии',
  'llm.cases': '✏️ Нейросеть — спорные случаи',
};

// Вопросы профиля (онбординг W11, 13.10.2026): ForceReply — ответ W3 «Route» узнаёт по началу текста вопроса
const PROFILE_PROMPTS = {
  profile: '✏️ Профиль — что поправить?',
  signature: '✍️ Подпись в письмах',
  contact: '📇 Контакт для HR',
  tz: '🕐 Часовой пояс',
  extra: '➕ Дополнительно к резюме',
  examples: '✉️ Образцы писем',
  rname: '✏️ Название резюме',
  newresume: '➕ Новое резюме',
};

// Вопросы рекомендаций по резюме (W13, 15.10.2026): ForceReply — ответ W3 «Route» узнаёт по началу текста вопроса
const RESUME_PROMPTS = {
  upgrade: '⬆️ Резюме — что добавить или поменять?',
  answer: '✍️ Резюме — свой ответ',
  plan: '✏️ Резюме — что я понял не так?',
  patch: '✏️ Резюме — как поправить правку?',
  exp: '💼 Опыт работы — что добавить или поменять?',
};

// Вопросы робота (этап 6, W9): фото капчи с ForceReply — ответ W3 «Route» узнаёт по началу подписи
const ROBOT_PROMPTS = { captcha: '🧩 Капча hh' };

// Вкладки списка: статусы строк (statuses = null — всё, кроме бэкфилла seen), порядок кнопок — порядок ключей
const TABS = {
  wait: { icon: '⏳', name: 'Ждут решения', statuses: ['waiting'] },
  todo: { icon: '✅', name: 'Откликнусь и 🤔', statuses: ['approved', 'maybe'] },
  sent: { icon: '📨', name: 'Отправлено', statuses: ['applied'] },
  skip: { icon: '❌', name: 'Мимо и устаревшие', statuses: ['skipped', 'expired', 'archived'] },
  rej: { icon: '🚫', name: 'Отсеяно фильтром', statuses: ['rejected'] },
  all: { icon: '📋', name: 'Все', statuses: null },
};

// Значки строки списка: решение нейросети + статус
const VERDICT_ICON = { apply: '🟢', maybe: '🟡', skip: '🔴', error: '⚠️' };
const STATUS_ICON = {
  new: '⚙️',
  detailed: '⚙️',
  scoring: '⚙️',
  waiting: '⏳',
  approved: '✅',
  maybe: '🤔',
  skipped: '❌',
  applied: '📨',
  expired: '⌛',
  archived: '🔒',
  rejected: '🚫',
};
// Значок строки с учётом робота: в очереди 🕒, отправляется 🤖, отправлен роботом 🚀
const statusIcon = (r) =>
  r.apply_state === 'queued'
    ? '🕒'
    : r.apply_state === 'applying'
      ? '🤖'
      : r.status === 'applied' && r.apply_by === 'robot'
        ? '🚀'
        : (STATUS_ICON[r.status] ?? '');

// Обновление — из триггера: между ним и «Route» стоит «Settings» (часовой пояс)
const update = $('Telegram Trigger').first().json;
const allowed = String($env.TG_CHAT_ID ?? '');
const ours = (chatId) => !allowed || String(chatId) === allowed;
const panel = (fields) => [
  { json: { action: 'panel', tab: '', page: 1, id: 0, queryId: '', messageId: 0, userMessageId: 0, ...fields } },
];

const cb = update.callback_query;
if (cb) {
  if (!ours(cb.message?.chat?.id)) return [];
  const data = String(cb.data ?? '');
  const chatId = String(cb.message.chat.id);
  const pressed = { chatId, queryId: cb.id, messageId: cb.message.message_id };

  // Профиль (W11): pf:view | pf:ok | pf:yes | pf:no | pf:e:<поле> | pf:g:<m|f> | pf:tz:<IANA> | pf:new:<all|text|no>
  const pf = data.match(/^pf:(view|ok|yes|no|e|g|tz|new)(?::(.+))?$/);
  if (pf) {
    const [, kind, arg = ''] = pf;
    const op = { view: 'view', ok: 'ok', yes: 'confirm', no: 'confirm', e: 'ask', g: 'set', tz: 'set', new: 'replace' }[kind];
    const field = { e: arg, g: 'gender', tz: 'tz' }[kind] ?? '';
    // pf:ok:<шаг> — шаг, на котором показали кнопку (W11 не перескочит шаг при двойном нажатии)
    const value = { ok: arg, yes: 'yes', no: 'no', g: arg, tz: arg, new: arg }[kind] ?? '';
    return [{ json: { action: 'profile', op, field, value, ...pressed, username: cb.from?.username ?? '' } }];
  }

  // Несколько резюме (W11, docs/resumes.md): rm:<действие>[:<id>[:<y|l>]] — действие в field, остальное в value
  const rm = data.match(/^rm:(list|new|o|on|off|ren|clone|del|txt|imp)(?::(r[1-5](?::[yl])?))?$/);
  if (rm) {
    return [{ json: { action: 'profile', op: 'rm', field: rm[1], value: rm[2] ?? '', ...pressed, username: cb.from?.username ?? '' } }];
  }
  // Импорт с hh: rm:i:<сессия из 4 знаков>:<номер резюме | b | x | go | next | retry | skip> — value = «сессия:действие»
  const imp = data.match(/^rm:i:([a-z0-9]{4}):(\d|b|x|go|next|retry|skip)$/);
  if (imp) {
    return [{ json: { action: 'profile', op: 'rm', field: 'i', value: `${imp[1]}:${imp[2]}`, ...pressed, username: cb.from?.username ?? '' } }];
  }

  // Рекомендации по резюме (W13): callback_data разбирает сам W13
  if (/^(rs|ru|rq|rp|rr|rc|rk|rx|re):/.test(data)) return [{ json: { action: 'resume', data, ...pressed } }];

  const list = data.match(/^p:l:([a-z]+):(\d+)$/);
  if (list && TABS[list[1]]) return panel({ ...pressed, view: 'list', tab: list[1], page: Number(list[2]) });
  if (data === 'p:s') return panel({ ...pressed, view: 'stats' });
  if (data === 'p:n') return panel({ chatId, queryId: cb.id, view: 'list', resume: true });
  if (data === 'p:x') return panel({ ...pressed, view: 'noop' });
  // 🤖 Автоотклик (6.1c): значение явное — двойное нажатие ▶️ не выключит
  const auto = data.match(/^au:(on|off|r)$/);
  if (auto) {
    return panel({ ...pressed, view: 'auto', ...(auto[1] !== 'r' && { change: { name: 'apply.auto', set: auto[1] === 'on' } }) });
  }

  // ⚙️ Настройки (W7): раздел, следующее значение настройки, «🔄 Собрать сейчас»
  const section = data.match(/^s:([a-z]+)$/);
  if (section) return panel({ ...pressed, view: 'settings', section: section[1] });
  const change = data.match(/^sc:([a-z_.]+)$/);
  if (change) {
    return panel({ ...pressed, view: 'settings', section: change[1].split('.')[0], change: { name: change[1] } });
  }
  if (data === 'sn') return panel({ ...pressed, view: 'settings', section: 'collect', collectNow: true });
  const toggle = data.match(/^st:([a-z_]+)$/);
  if (toggle) {
    return panel({ ...pressed, view: 'settings', section: 'rules', change: { name: 'filter.rules_off', toggle: toggle[1] } });
  }
  const ask = data.match(/^sw:([a-z_.]+)$/);
  if (ask && SETTING_PROMPTS[ask[1]]) {
    return panel({ ...pressed, view: 'settings', section: ask[1].split('.')[0], ask: ask[1] });
  }
  const unban = data.match(/^bld:(\d+)$/);
  if (unban) return panel({ ...pressed, view: 'settings', section: 'blacklist', unban: Number(unban[1]) });

  // Робот-отклик (этап 6): 🚀 под письмом, ⛔ из очереди, ▶️ после блока → W9 Robot
  const robot = data.match(/^l:(\d+):(robot|stop)$/);
  if (robot) {
    return [{ json: { action: 'robot', op: robot[2] === 'robot' ? 'enqueue' : 'stop', id: Number(robot[1]), ...pressed } }];
  }
  if (data === 'rb:go') return [{ json: { action: 'robot', op: 'resume', id: 0, ...pressed } }];

  const letter = data.match(/^l:(\d+):(redo|sent|unsent|cancel)$/);
  if (letter) {
    return [{ json: { action: 'letter', id: Number(letter[1]), op: letter[2], ...pressed } }];
  }
  const fromPanel = data.match(/^pv:(\d+):(apply|maybe|skip|earlier|ban|edit|score):([a-z]+):(\d+)$/);
  if (fromPanel) {
    const tab = TABS[fromPanel[3]] ? fromPanel[3] : 'all';
    return [
      {
        json: {
          action: 'choice',
          id: Number(fromPanel[1]),
          choice: fromPanel[2],
          ...pressed,
          panel: { messageId: cb.message.message_id, tab, page: Number(fromPanel[4]) },
        },
      },
    ];
  }
  const match = data.match(/^v:(\d+):(apply|maybe|skip|earlier|ban|edit)$/);
  if (!match) return [];
  return [{ json: { action: 'choice', id: Number(match[1]), choice: match[2], ...pressed, panel: null } }];
}

const msg = update.message;
if (!msg || !ours(msg.chat?.id)) return [];
const text = String(msg.text ?? '').trim();
const typed = { chatId: String(msg.chat.id), userMessageId: msg.message_id };

// Документ в чате — резюме (W11): PDF разберём, остальное — подскажем, что нужен PDF
if (msg.document) {
  const d = msg.document;
  const pdf = d.mime_type === 'application/pdf' || /\.pdf$/i.test(d.file_name ?? '');
  return [
    {
      json: {
        action: 'profile',
        op: pdf ? 'pdf' : 'not_pdf',
        file: { id: d.file_id, name: String(d.file_name ?? ''), size: Number(d.file_size ?? 0) },
        ...typed,
        username: msg.from?.username ?? '',
      },
    },
  ];
}

// Ответ на вопрос профиля (W11): поле — по началу текста вопроса
const profilePrompt = Object.keys(PROFILE_PROMPTS).find((key) =>
  String(msg.reply_to_message?.text ?? '').startsWith(PROFILE_PROMPTS[key]),
);
if (profilePrompt && text) {
  return [
    {
      json: {
        action: 'profile',
        op: 'input',
        field: profilePrompt,
        text: text.slice(0, 4000),
        ...typed,
        promptId: msg.reply_to_message.message_id,
        username: msg.from?.username ?? '',
      },
    },
  ];
}

// Ответ на вопрос рекомендаций по резюме (W13): поле — по началу текста вопроса
const resumePrompt = Object.keys(RESUME_PROMPTS).find((key) =>
  String(msg.reply_to_message?.text ?? '').startsWith(RESUME_PROMPTS[key]),
);
if (resumePrompt && text) {
  return [
    {
      json: {
        action: 'resume',
        op: 'input',
        field: resumePrompt,
        text: text.slice(0, 4000),
        ...typed,
        promptId: msg.reply_to_message.message_id,
      },
    },
  ];
}

// Кнопки под полем ввода и команды: /v169 → [v, 169], /stats@bot → [stats, '']
const command = text.match(/^\/([a-z]+)(\d*)(?:@\w+)?(?:\s|$)/i);
const name = command?.[1].toLowerCase();
if (text === MENU.list || name === 'vacancies') return panel({ ...typed, view: 'list' });
if (text === MENU.stats || name === 'stats') return panel({ ...typed, view: 'stats' });
if (text === MENU.auto || name === 'auto') return panel({ ...typed, view: 'auto' });
if (text === MENU.settings || name === 'settings') return panel({ ...typed, view: 'settings', section: 'root' });
if (name === 'start' || name === 'menu') return panel({ ...typed, view: 'start' });
if (name === 'v' && command[2]) return panel({ ...typed, view: 'open', id: Number(command[2]) });
// /bl12 — убрать компанию из чёрного списка (панель спросит подтверждение)
if (name === 'bl' && command[2]) return panel({ ...typed, view: 'settings', section: 'unban', id: Number(command[2]) });
// /go — робот, продолжай (после капчи или входа через «Общий экран»)
const robotJob = (fields) => [{ json: { action: 'robot', id: 0, queryId: '', messageId: 0, ...typed, ...fields } }];
if (name === 'go') return robotJob({ op: 'resume' });

// Ответ на фото капчи (W9): у фото нет text — подпись в caption
const replied = msg.reply_to_message;
if (replied && text && String(replied.caption ?? replied.text ?? '').startsWith(ROBOT_PROMPTS.captcha)) {
  return robotJob({ op: 'captcha', text: text.slice(0, 40), promptId: replied.message_id });
}

// Ответ на вопрос ⚙️ со списком — новый список (вопрос узнаём по началу его текста)
const prompt = Object.keys(SETTING_PROMPTS).find((key) =>
  String(msg.reply_to_message?.text ?? '').startsWith(SETTING_PROMPTS[key]),
);
if (prompt && text) {
  return panel({
    ...typed,
    view: 'settings',
    section: prompt.split('.')[0],
    input: { name: prompt, text: text.slice(0, 1000) },
    promptId: msg.reply_to_message.message_id,
  });
}

// Остальные команды и сообщения без reply не обрабатываем
if (msg.reply_to_message && text && !text.startsWith('/')) {
  return [
    {
      json: {
        action: 'reply',
        replyTo: msg.reply_to_message.message_id,
        messageId: msg.message_id,
        chatId: typed.chatId,
        text: text.slice(0, 500),
      },
    },
  ];
}
return [];

// W3 · Rescue parse — страница вакансии, отсеянной фильтром, перед решением с панели (08.10.2026).
// Нода: Code, режим «Run Once for All Items».
// Отсеянные по выдаче страницу не открывали — описания нет, а оно нужно письму (✅) и нейросети (🤖 На оценку).
// Вход: ответ HTTP Request «Rescue page»; строка — из «Vacancy».
// Выход: { id, description, key_skills, has_test, contract, error, closed } → «Save page» (запись по id) → «Apply choice».
//   Страница не открылась — решение всё равно принимаем: письмо и оценка пойдут по фрагменту, ошибка видна в карточке.
//   closed — вакансия в архиве или закрыта для откликов: «Apply choice» поставит «🔒 закрыта».
//   Правила фильтра по странице не применяем: пользователь сам решил вернуть вакансию.

// Общий код разбора страницы вакансии hh: W1 «Parse vacancy», W3 «Rescue parse» и W6 «Archive status».
// В Code-ноду попадает строкой «// @include n8n/shared/hh.js».

// HTML-сущности раскодируем за один проход: иначе &amp;quot; станет кавычкой и сломает JSON
const NAMED = { quot: '"', amp: '&', lt: '<', gt: '>', apos: "'", nbsp: '\u00a0' };
function decodeEntities(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const code = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(code) && code <= 0x10ffff ? String.fromCodePoint(code) : m;
    }
    return NAMED[e.toLowerCase()] ?? m;
  });
}

// Ответ HTTP Request «Vacancy page» → { v: vacancyFull.vacancy, test } или { error, statusCode }
function parsePage(res) {
  const html = String(res.data ?? res.body ?? '');
  if (res.statusCode !== 200) return { error: `страница: HTTP ${res.statusCode}`, statusCode: res.statusCode };
  const tpl = html.match(/<template[^>]*id="HH-Lux-InitialState"[^>]*>([\s\S]*?)<\/template>/);
  if (!tpl) return { error: 'страница: нет HH-Lux-InitialState' };
  try {
    const state = JSON.parse(decodeEntities(tpl[1]));
    const v = state?.vacancyView?.vacancyFull?.vacancy;
    if (!v?.description) return { error: 'страница: нет описания' };
    return { v, test: state?.applicantVacancyResponseStatuses?.[String(v.vacancyId)]?.test };
  } catch (e) {
    return { error: `страница: ${e.message}` };
  }
}

// Описание вакансии: HTML → текст с переносами строк
const htmlToText = (html) =>
  decodeEntities(
    String(html ?? '')
      .replace(/<\s*(br|\/p|\/li|\/h\d|\/div)[^>]*>/gi, '\n')
      .replace(/<li[^>]*>/gi, '• ')
      .replace(/<[^>]+>/g, ''),
  )
    .replace(/[ \t\u00a0]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim();

// Форма оформления: tk,self_employed,individual_entrepreneur,individual_person (колонка contract)
const contractOf = (v) =>
  [
    ...(v.acceptLaborContract ? ['tk'] : []),
    ...(v.civilLawContracts ?? []).flatMap((c) => c?.civilLawContractsElement ?? (typeof c === 'string' ? [c] : [])).map((c) => String(c).toLowerCase()),
  ].join(',');

const row = $('Vacancy').first().json;
let page = parsePage($input.first().json);
if (!page.error && String(page.v.vacancyId) !== String(row.external_id)) {
  page = { error: `страница: пришла вакансия ${page.v.vacancyId}` };
}

if (page.error) {
  return [
    {
      json: {
        id: row.id,
        description: row.description ?? '',
        key_skills: row.key_skills ?? '',
        has_test: Boolean(row.has_test),
        contract: row.contract ?? '',
        error: page.error,
        closed: false,
      },
    },
  ];
}

const { v, test } = page;
const skills = (v.keySkills ?? []).join(', ');
return [
  {
    json: {
      id: row.id,
      description: htmlToText(v.description).slice(0, 8000),
      key_skills: skills || row.key_skills || '',
      has_test: Boolean(test?.hasTests ?? row.has_test),
      contract: contractOf(v),
      error: '',
      closed: Boolean(v.status?.archived || v.closedForApplicants),
    },
  },
];

// W3 · Apply choice — нажатие кнопки на карточке → новое состояние строки и карточки.
// Нода: Code, режим «Run Once for All Items».
// Вход: строка вакансии из «Vacancy»; что нажато — из «Route».
// Выход: { id, my_decision, status, text, keyboard, ask, toast, need_letter, chatId, messageId, queryId, panel }
//   messageId — исходная карточка в ленте: её перерисовывают «Card: …», на неё отвечает «Почему?».
//   Решение из карточки на панели меню (panel, callback_data pv:…) — тоже правит исходную карточку
//   (row.tg_message_id), а панель потом перерисует W7 («From panel?» → «Panel job»).
//   ✅ / 🤔 / ❌ — записать решение, кнопки сменить на «↩️ Изменить» (keyboard = decided).
//     Решение расходится с нейросетью и причины ещё нет → ask: вопрос «почему?» ответом на карточку.
//     ✅ и письма ещё нет → need_letter: W5 напишет письмо (этап 4).
//   📨 Уже откликался (choice = earlier) — status = applied без письма; «почему?» не спрашиваем:
//     отклик был до бота, в теневой режим не идёт.
//   🚫 В ЧС (choice = ban, 07.10.2026) — ❌ с причиной «чёрный список» без «почему?»; ban = компания → «Ban company».
//   ↩️ Изменить (choice = edit) — вернуть кнопки выбора (keyboard = choose), решение не меняется.
//   Отсеянная фильтром (status = rejected, 08.10.2026) — решение с панели меню, карточки в ленте у неё нет:
//     ✅ / 🤔 / 📨 — new_card: W3 отправит карточку в ленту (на неё ответит «Почему?» и письмо), «Почему?» —
//     с причинами фильтра (по ответам правим фильтр); 🤖 На оценку (choice = score) — status = detailed,
//     score: W3 сразу запустит W2, карточку пришлёт он. Страница с hh («Rescue parse») закрыта — «🔒 закрыта».
//   keyboard: decided | choose | none (карточки нет или перерисовывать нечего).
//   Вакансия в очереди робота (apply_state ≠ '', этап 6) — решение не меняется, тост «сначала ⛔ под письмом».

// Время человека (13.10.2026, docs/onboarding.md): часовой пояс — настройка profile.tz (IANA, например Asia/Bangkok),
// иначе пояс компьютера (USER_TZ из .env — его пишет мастер установки), иначе Москва. Расписание сбора по-прежнему
// считается по Москве (n8n/shared/schedule.js): hh публикует вакансии по МСК.
// Общий код: строка «// @include n8n/shared/time.js» — раньше n8n/shared/card.js и n8n/shared/robot.js (им нужен TZ).
// Пояс берётся из ноды «Settings», если она есть в workflow и уже выполнилась; без неё — USER_TZ.

const MSK_TZ = 'Europe/Moscow';
const validTz = (tz) => {
  try {
    return Boolean(tz) && Boolean(new Intl.DateTimeFormat('en-GB', { timeZone: tz }));
  } catch {
    return false;
  }
};

// Пояс этого запуска
function currentTz() {
  let tz = '';
  try {
    const row = $('Settings')
      .all()
      .map((i) => i.json)
      .find((r) => r?.name === 'profile.tz');
    tz = row ? JSON.parse(row.value_json) : '';
  } catch {
    // в workflow нет ноды «Settings» или строка битая — пояс компьютера
  }
  const env = typeof $env === 'undefined' ? '' : $env.USER_TZ;
  return [tz, env, MSK_TZ].find(validTz);
}
const TZ = currentTz();

// Части даты в поясе tz числами: { y, mo, d, h, mi }
function zonedParts(ms, tz = TZ) {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  }).formatToParts(new Date(ms));
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  return { y: get('year'), mo: get('month'), d: get('day'), h: get('hour'), mi: get('minute') };
}
const pad2 = (n) => String(n).padStart(2, '0');

// 1760340720000 → '14:32'
const localHM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.h)}:${pad2(p.mi)}`;
};
// → '07.10'
const localDM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.d)}.${pad2(p.mo)}`;
};
// → '2026-10-07' — ключ дня
const localDay = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${p.y}-${pad2(p.mo)}-${pad2(p.d)}`;
};
const localHour = (ms, tz = TZ) => zonedParts(ms, tz).h;

// Смещение пояса от UTC в минутах в момент ms (Бангкок: +420)
function tzOffsetMin(ms, tz = TZ) {
  const p = zonedParts(ms, tz);
  return Math.round((Date.UTC(p.y, p.mo - 1, p.d, p.h, p.mi) - Math.floor(ms / 60000) * 60000) / 60000);
}

// 'UTC+7', 'UTC+5:30', 'UTC−4'
function tzLabel(tz = TZ, ms = Date.now()) {
  const off = tzOffsetMin(ms, tz);
  const abs = Math.abs(off);
  return `UTC${off < 0 ? '−' : '+'}${Math.floor(abs / 60)}${abs % 60 ? `:${pad2(abs % 60)}` : ''}`;
}

// Начало «дня», который начинается в hour:00 по местному: последний такой момент не позже ms
function localDayStart(ms, tz = TZ, hour = 0) {
  const p = zonedParts(ms, tz);
  let start = Date.UTC(p.y, p.mo - 1, p.d, hour) - tzOffsetMin(ms, tz) * 60000;
  if (start > ms) start -= 24 * 3600 * 1000;
  return start;
}

// Тихие часы 23:00–09:00 по местному: карточки и сводка — без звука, тревоги — со звуком
const quietHours = (ms = Date.now(), tz = TZ) => {
  const h = localHour(ms, tz);
  return h >= 23 || h < 9;
};

// Время по местному и в скобках по Москве: '14:32 (10:32 МСК)'; пояс совпадает с Москвой — '10:32 МСК'
const localMsk = (ms, tz = TZ) =>
  tzOffsetMin(ms, tz) === tzOffsetMin(ms, MSK_TZ) ? `${localHM(ms, MSK_TZ)} МСК` : `${localHM(ms, tz)} (${localHM(ms, MSK_TZ)} МСК)`;

// Момент ISO (applied_at) → дата и время по местному: '2026-10-06T21:17:55Z' → '07.10', '04:17'
const localDate = (iso) => (Date.parse(iso) ? localDM(Date.parse(iso)) : '');
const localTime = (iso) => (Date.parse(iso) ? localHM(Date.parse(iso)) : '');

// Общий код карточки вакансии в Telegram: W2 «Format card» и W3 «Apply choice».
// В Code-ноду попадает при сборке: строка «// @include n8n/shared/card.js» заменяется этим файлом
// (scripts/build-workflows.mjs, scripts/run-code-node.mjs). Раньше него — n8n/shared/time.js (localDate).

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const EXPERIENCE = { noExperience: 'без опыта', between1And3: '1–3 г.', between3And6: '3–6 л.', moreThan6: '6+ л.' };
const CURRENCY = { RUR: '₽', USD: '$', EUR: '€', KZT: '₸', BYR: 'Br', UZS: 'сум' };

// Решение нейросети (колонка decision)
const VERDICT = { apply: '🟢 apply', maybe: '🟡 maybe', skip: '🔴 skip', error: '⚠️ не оценено' };
// Подписи моделей нейросети (19.10.2026, docs/claude-cli.md): шапка письма (letter_model) и кнопки ⚙️ → 🤖
const MODEL_LABELS = {
  'claude-haiku-5-5': 'Haiku 5.5',
  'claude-sonnet-5-5': 'Sonnet 5.5',
  'claude-opus-5-5': 'Opus 5.5',
  'claude-haiku-4-5': 'Haiku 4.5',
};
// 'gemini-3.5-flash-lite' → 'Gemini 3.5 Flash-Lite'; неизвестная модель — как есть
function modelLabel(id) {
  const name = String(id ?? '');
  if (MODEL_LABELS[name]) return MODEL_LABELS[name];
  if (!name.startsWith('gemini-')) return name;
  const words = name.slice(7).split('-').map((w) => w.charAt(0).toUpperCase() + w.slice(1));
  return `Gemini ${words.join('-')}`.replace(/(\d)-/, '$1 ');
}
// Кнопки пользователя: callback_data = v:<id строки>:<choice>, решение — в колонку my_decision.
// earlier — «📨 Уже откликался» (до бота, 07.10.2026): status = applied без письма и без applied_at,
// без «Почему?» и вне теневого режима (сравниваются только apply / maybe / skip)
const CHOICE = { apply: '✅ Откликнусь', maybe: '🤔 Возможно', skip: '❌ Мимо', earlier: '📨 Откликался раньше' };
// «🚫 В ЧС» на карточке (07.10.2026): компания уходит в чёрный список, вакансия — ❌ с этой причиной
const BAN_REASON = 'чёрный список';
const STATUS_BY_CHOICE = { apply: 'approved', maybe: 'maybe', skip: 'skipped', earlier: 'applied' };

const short = (n) => (n >= 1000 ? `${Math.round(n / 1000)}k` : String(n));

function salary(r) {
  if (!r.salary_from && !r.salary_to) return '';
  const range =
    r.salary_from && r.salary_to
      ? `${short(r.salary_from)}–${short(r.salary_to)}`
      : r.salary_from
        ? `от ${short(r.salary_from)}`
        : `до ${short(r.salary_to)}`;
  return `💰 ${range} ${CURRENCY[r.currency] ?? r.currency ?? ''}${r.salary_gross ? ' до налогов' : ''}`;
}

// «Москва, Сербия, Грузия, Армения» → «Москва, Сербия +2»
function areas(s) {
  const list = String(s ?? '').split(', ').filter(Boolean);
  return list.length > 2 ? `${list.slice(0, 2).join(', ')} +${list.length - 2}` : list.join(', ');
}

// '2026-10-06T13:22:00+0300' → '06.10'
function published(s) {
  const m = String(s ?? '').match(/^\d{4}-(\d{2})-(\d{2})/);
  return m ? `${m[2]}.${m[1]}` : '';
}

// Итоговые состояния без кнопок: W3 «📨 Отправил», W6 «⌛ устарела» и «🔒 закрыта на hh»
const FINAL = { expired: '⌛ Устарела: 3 дня без решения', archived: '🔒 Вакансия закрыта на hh' };

// Текст карточки (Parse Mode = HTML). Строка «👤 …» появляется после нажатия кнопки,
// «📨 …» — после «Отправил» под письмом (W3, status = applied), FINAL — после W6
function cardText(r) {
  const date = published(r.published_at);
  const meta = [esc(r.company), salary(r), EXPERIENCE[r.experience] ?? '', esc(areas(r.areas)), date && `📅 ${date}`]
    .filter(Boolean)
    .join(' · ');
  const flags = [
    r.has_test && '📝 тест',
    r.letter_required && '✉️ письмо обязательно',
    r.responses != null && `👥 ${r.responses}`,
    r.error && `⚠️ ${esc(r.error)}`,
  ]
    .filter(Boolean)
    .join(' · ');
  // Нейросеть не оценивала, а фильтр отсеял (в том числе вакансия, возвращённая с панели меню, 08.10.2026) — причины фильтра
  const verdict =
    !r.decision && r.reasons
      ? `🧹 Отсеяна фильтром: ${esc(r.reasons)}`
      : `🤖 ${VERDICT[r.decision] ?? esc(r.decision)}${r.llm_reason ? ` — ${esc(r.llm_reason)}` : ''}`;
  // Автоотклик (6.1c): решение за пользователя принял робот по apply нейросети — вместо строки «👤 …»
  const mine = CHOICE[r.my_decision]
    ? `👤 ${CHOICE[r.my_decision]}${r.my_reason === BAN_REASON ? ' · 🚫 компания в чёрном списке' : ''}`
    : r.apply_mode === 'auto' && ['approved', 'applied'].includes(r.status)
      ? '🤖 Автоотклик'
      : '';
  // «📨 Откликался раньше» уже в строке «👤 …» — второй раз не пишем
  // Робот (этап 6): «🚀 … роботом»; нашёлся на hh без «📨 Отправил» (6.2) — «📨 … на hh»
  const who = r.apply_by === 'robot' ? '🚀 Отклик отправлен роботом' : r.apply_by === 'hh' ? '📨 Отклик есть на hh' : '📨 Отклик отправлен';
  const sent =
    r.status === 'applied' && r.my_decision !== 'earlier' ? `${who}${r.applied_at ? ` ${localDate(r.applied_at)}` : ''}` : '';
  // Несколько резюме (docs/resumes.md): каким резюме вакансия. resume_name пишет W1 всем вакансиям, пока резюме
  // больше одного (у основного resume_id пустой), и обновляет W11 при переименовании и удалении резюме
  const resume = r.resume_name ? `📄 Резюме: ${esc(r.resume_name)}` : '';
  return [`<a href="${r.url}"><b>${esc(r.title)}</b></a>`, meta, resume, flags, verdict, mine, sent, FINAL[r.status] ?? '']
    .filter(Boolean)
    .join('\n');
}

const action = $('Route').first().json;
const row = $input.first().json;

const out = {
  id: row.id,
  my_decision: row.my_decision ?? '',
  // Причину не затираем: «Save choice» пишет её всегда
  my_reason: row.my_reason ?? '',
  status: row.status,
  keyboard: 'choose',
  ask: '',
  toast: '',
  need_letter: false,
  chatId: action.chatId,
  messageId: action.panel ? row.tg_message_id : action.messageId,
  queryId: action.queryId,
  panel: action.panel ?? null,
  ban: null,
  new_card: false,
  score: false,
};
// Страница, загруженная перед решением (только у отсеянных без описания)
let page = null;
try {
  page = $('Rescue parse').first().json;
} catch {
  // не загружали
}
const rescue = row.status === 'rejected' && action.choice !== 'edit';

// Робот (этап 6) уже взял вакансию в очередь или отправляет отклик — решение не меняем
if (row.apply_state) {
  out.keyboard = 'none';
  out.toast = '🚀 Робот в работе — сначала ⛔ под письмом';
  out.text = cardText(row);
  return [{ json: out }];
}

if (rescue && page?.closed) {
  out.status = 'archived';
  out.keyboard = 'none';
  out.toast = '🔒 Вакансия уже закрыта на hh';
} else if (rescue && action.choice === 'score') {
  out.status = 'detailed';
  out.keyboard = 'none';
  out.score = true;
  out.toast = '🤖 Отправил нейросети — карточка придёт в ленту';
} else if (action.choice === 'score') {
  out.keyboard = 'none'; // «На оценку» — только для отсеянных
} else if (rescue) {
  out.my_decision = action.choice;
  out.status = STATUS_BY_CHOICE[action.choice];
  out.keyboard = 'decided';
  out.toast = `Записал: ${CHOICE[action.choice]}`;
  out.need_letter = action.choice === 'apply' && !row.letter;
  out.new_card = !row.tg_message_id;
  if (action.choice !== 'earlier' && !row.my_reason) {
    out.ask =
      `🧹 Фильтр: ${esc(row.reasons || 'отсеял')} · 👤 ${CHOICE[action.choice]}\n` +
      'Почему? Ответь на это сообщение одной фразой — по ответам поправлю фильтр.';
  }
} else if (action.choice === 'ban') {
  out.my_decision = 'skip';
  out.my_reason = BAN_REASON;
  out.status = STATUS_BY_CHOICE.skip;
  out.keyboard = 'decided';
  out.toast = `🚫 ${row.company || 'Компания'} — в чёрном списке`;
  out.ban = { company: row.company ?? '', company_id: row.company_id ?? '', title: row.title ?? '' };
} else if (action.choice !== 'edit') {
  out.my_decision = action.choice;
  out.status = STATUS_BY_CHOICE[action.choice];
  out.keyboard = 'decided';
  out.toast = `Записал: ${CHOICE[action.choice]}`;
  out.need_letter = action.choice === 'apply' && !row.letter;
  const known = ['apply', 'maybe', 'skip'].includes(row.decision);
  if (action.choice !== 'earlier' && known && row.decision !== action.choice && !row.my_reason) {
    out.ask =
      `🤖 ${VERDICT[row.decision]} · 👤 ${CHOICE[action.choice]}\n` +
      'Почему? Ответь на это сообщение одной фразой — по ответам поправлю правила.';
  }
}
out.text = cardText({ ...row, ...(page ?? {}), my_decision: out.my_decision, my_reason: out.my_reason, status: out.status });

return [{ json: out }];

// W3 · Apply sent — кнопки под письмом «📨 Отправил» и «↩️ Отменить».
// Нода: Code, режим «Run Once for All Items».
// Вход: строка вакансии из «Sent row», кнопка — из «Route» (op = sent | unsent; messageId — сообщение с письмом).
// Выход: { id, sent, busy, status, applied_at, apply_by, robot, robot_button, letterText, cardText, chatId, letterMessageId,
//          cardId, queryId, toast, apply_url, url }
//   sent   — status = applied; у письма остаётся только «↩️ Отменить», у карточки кнопки убираются;
//   unsent — status = approved; письму возвращаются все кнопки (с 🚀, если подходит роботу), карточке — «↩️ Изменить».
//   busy — вакансия в очереди робота (этап 6): ничего не меняем, только тост. «📨 Отправил» пишет apply_by = me.

// Время человека (13.10.2026, docs/onboarding.md): часовой пояс — настройка profile.tz (IANA, например Asia/Bangkok),
// иначе пояс компьютера (USER_TZ из .env — его пишет мастер установки), иначе Москва. Расписание сбора по-прежнему
// считается по Москве (n8n/shared/schedule.js): hh публикует вакансии по МСК.
// Общий код: строка «// @include n8n/shared/time.js» — раньше n8n/shared/card.js и n8n/shared/robot.js (им нужен TZ).
// Пояс берётся из ноды «Settings», если она есть в workflow и уже выполнилась; без неё — USER_TZ.

const MSK_TZ = 'Europe/Moscow';
const validTz = (tz) => {
  try {
    return Boolean(tz) && Boolean(new Intl.DateTimeFormat('en-GB', { timeZone: tz }));
  } catch {
    return false;
  }
};

// Пояс этого запуска
function currentTz() {
  let tz = '';
  try {
    const row = $('Settings')
      .all()
      .map((i) => i.json)
      .find((r) => r?.name === 'profile.tz');
    tz = row ? JSON.parse(row.value_json) : '';
  } catch {
    // в workflow нет ноды «Settings» или строка битая — пояс компьютера
  }
  const env = typeof $env === 'undefined' ? '' : $env.USER_TZ;
  return [tz, env, MSK_TZ].find(validTz);
}
const TZ = currentTz();

// Части даты в поясе tz числами: { y, mo, d, h, mi }
function zonedParts(ms, tz = TZ) {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  }).formatToParts(new Date(ms));
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  return { y: get('year'), mo: get('month'), d: get('day'), h: get('hour'), mi: get('minute') };
}
const pad2 = (n) => String(n).padStart(2, '0');

// 1760340720000 → '14:32'
const localHM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.h)}:${pad2(p.mi)}`;
};
// → '07.10'
const localDM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.d)}.${pad2(p.mo)}`;
};
// → '2026-10-07' — ключ дня
const localDay = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${p.y}-${pad2(p.mo)}-${pad2(p.d)}`;
};
const localHour = (ms, tz = TZ) => zonedParts(ms, tz).h;

// Смещение пояса от UTC в минутах в момент ms (Бангкок: +420)
function tzOffsetMin(ms, tz = TZ) {
  const p = zonedParts(ms, tz);
  return Math.round((Date.UTC(p.y, p.mo - 1, p.d, p.h, p.mi) - Math.floor(ms / 60000) * 60000) / 60000);
}

// 'UTC+7', 'UTC+5:30', 'UTC−4'
function tzLabel(tz = TZ, ms = Date.now()) {
  const off = tzOffsetMin(ms, tz);
  const abs = Math.abs(off);
  return `UTC${off < 0 ? '−' : '+'}${Math.floor(abs / 60)}${abs % 60 ? `:${pad2(abs % 60)}` : ''}`;
}

// Начало «дня», который начинается в hour:00 по местному: последний такой момент не позже ms
function localDayStart(ms, tz = TZ, hour = 0) {
  const p = zonedParts(ms, tz);
  let start = Date.UTC(p.y, p.mo - 1, p.d, hour) - tzOffsetMin(ms, tz) * 60000;
  if (start > ms) start -= 24 * 3600 * 1000;
  return start;
}

// Тихие часы 23:00–09:00 по местному: карточки и сводка — без звука, тревоги — со звуком
const quietHours = (ms = Date.now(), tz = TZ) => {
  const h = localHour(ms, tz);
  return h >= 23 || h < 9;
};

// Время по местному и в скобках по Москве: '14:32 (10:32 МСК)'; пояс совпадает с Москвой — '10:32 МСК'
const localMsk = (ms, tz = TZ) =>
  tzOffsetMin(ms, tz) === tzOffsetMin(ms, MSK_TZ) ? `${localHM(ms, MSK_TZ)} МСК` : `${localHM(ms, tz)} (${localHM(ms, MSK_TZ)} МСК)`;

// Момент ISO (applied_at) → дата и время по местному: '2026-10-06T21:17:55Z' → '07.10', '04:17'
const localDate = (iso) => (Date.parse(iso) ? localDM(Date.parse(iso)) : '');
const localTime = (iso) => (Date.parse(iso) ? localHM(Date.parse(iso)) : '');

// Общий код карточки вакансии в Telegram: W2 «Format card» и W3 «Apply choice».
// В Code-ноду попадает при сборке: строка «// @include n8n/shared/card.js» заменяется этим файлом
// (scripts/build-workflows.mjs, scripts/run-code-node.mjs). Раньше него — n8n/shared/time.js (localDate).

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const EXPERIENCE = { noExperience: 'без опыта', between1And3: '1–3 г.', between3And6: '3–6 л.', moreThan6: '6+ л.' };
const CURRENCY = { RUR: '₽', USD: '$', EUR: '€', KZT: '₸', BYR: 'Br', UZS: 'сум' };

// Решение нейросети (колонка decision)
const VERDICT = { apply: '🟢 apply', maybe: '🟡 maybe', skip: '🔴 skip', error: '⚠️ не оценено' };
// Подписи моделей нейросети (19.10.2026, docs/claude-cli.md): шапка письма (letter_model) и кнопки ⚙️ → 🤖
const MODEL_LABELS = {
  'claude-haiku-5-5': 'Haiku 5.5',
  'claude-sonnet-5-5': 'Sonnet 5.5',
  'claude-opus-5-5': 'Opus 5.5',
  'claude-haiku-4-5': 'Haiku 4.5',
};
// 'gemini-3.5-flash-lite' → 'Gemini 3.5 Flash-Lite'; неизвестная модель — как есть
function modelLabel(id) {
  const name = String(id ?? '');
  if (MODEL_LABELS[name]) return MODEL_LABELS[name];
  if (!name.startsWith('gemini-')) return name;
  const words = name.slice(7).split('-').map((w) => w.charAt(0).toUpperCase() + w.slice(1));
  return `Gemini ${words.join('-')}`.replace(/(\d)-/, '$1 ');
}
// Кнопки пользователя: callback_data = v:<id строки>:<choice>, решение — в колонку my_decision.
// earlier — «📨 Уже откликался» (до бота, 07.10.2026): status = applied без письма и без applied_at,
// без «Почему?» и вне теневого режима (сравниваются только apply / maybe / skip)
const CHOICE = { apply: '✅ Откликнусь', maybe: '🤔 Возможно', skip: '❌ Мимо', earlier: '📨 Откликался раньше' };
// «🚫 В ЧС» на карточке (07.10.2026): компания уходит в чёрный список, вакансия — ❌ с этой причиной
const BAN_REASON = 'чёрный список';
const STATUS_BY_CHOICE = { apply: 'approved', maybe: 'maybe', skip: 'skipped', earlier: 'applied' };

const short = (n) => (n >= 1000 ? `${Math.round(n / 1000)}k` : String(n));

function salary(r) {
  if (!r.salary_from && !r.salary_to) return '';
  const range =
    r.salary_from && r.salary_to
      ? `${short(r.salary_from)}–${short(r.salary_to)}`
      : r.salary_from
        ? `от ${short(r.salary_from)}`
        : `до ${short(r.salary_to)}`;
  return `💰 ${range} ${CURRENCY[r.currency] ?? r.currency ?? ''}${r.salary_gross ? ' до налогов' : ''}`;
}

// «Москва, Сербия, Грузия, Армения» → «Москва, Сербия +2»
function areas(s) {
  const list = String(s ?? '').split(', ').filter(Boolean);
  return list.length > 2 ? `${list.slice(0, 2).join(', ')} +${list.length - 2}` : list.join(', ');
}

// '2026-10-06T13:22:00+0300' → '06.10'
function published(s) {
  const m = String(s ?? '').match(/^\d{4}-(\d{2})-(\d{2})/);
  return m ? `${m[2]}.${m[1]}` : '';
}

// Итоговые состояния без кнопок: W3 «📨 Отправил», W6 «⌛ устарела» и «🔒 закрыта на hh»
const FINAL = { expired: '⌛ Устарела: 3 дня без решения', archived: '🔒 Вакансия закрыта на hh' };

// Текст карточки (Parse Mode = HTML). Строка «👤 …» появляется после нажатия кнопки,
// «📨 …» — после «Отправил» под письмом (W3, status = applied), FINAL — после W6
function cardText(r) {
  const date = published(r.published_at);
  const meta = [esc(r.company), salary(r), EXPERIENCE[r.experience] ?? '', esc(areas(r.areas)), date && `📅 ${date}`]
    .filter(Boolean)
    .join(' · ');
  const flags = [
    r.has_test && '📝 тест',
    r.letter_required && '✉️ письмо обязательно',
    r.responses != null && `👥 ${r.responses}`,
    r.error && `⚠️ ${esc(r.error)}`,
  ]
    .filter(Boolean)
    .join(' · ');
  // Нейросеть не оценивала, а фильтр отсеял (в том числе вакансия, возвращённая с панели меню, 08.10.2026) — причины фильтра
  const verdict =
    !r.decision && r.reasons
      ? `🧹 Отсеяна фильтром: ${esc(r.reasons)}`
      : `🤖 ${VERDICT[r.decision] ?? esc(r.decision)}${r.llm_reason ? ` — ${esc(r.llm_reason)}` : ''}`;
  // Автоотклик (6.1c): решение за пользователя принял робот по apply нейросети — вместо строки «👤 …»
  const mine = CHOICE[r.my_decision]
    ? `👤 ${CHOICE[r.my_decision]}${r.my_reason === BAN_REASON ? ' · 🚫 компания в чёрном списке' : ''}`
    : r.apply_mode === 'auto' && ['approved', 'applied'].includes(r.status)
      ? '🤖 Автоотклик'
      : '';
  // «📨 Откликался раньше» уже в строке «👤 …» — второй раз не пишем
  // Робот (этап 6): «🚀 … роботом»; нашёлся на hh без «📨 Отправил» (6.2) — «📨 … на hh»
  const who = r.apply_by === 'robot' ? '🚀 Отклик отправлен роботом' : r.apply_by === 'hh' ? '📨 Отклик есть на hh' : '📨 Отклик отправлен';
  const sent =
    r.status === 'applied' && r.my_decision !== 'earlier' ? `${who}${r.applied_at ? ` ${localDate(r.applied_at)}` : ''}` : '';
  // Несколько резюме (docs/resumes.md): каким резюме вакансия. resume_name пишет W1 всем вакансиям, пока резюме
  // больше одного (у основного resume_id пустой), и обновляет W11 при переименовании и удалении резюме
  const resume = r.resume_name ? `📄 Резюме: ${esc(r.resume_name)}` : '';
  return [`<a href="${r.url}"><b>${esc(r.title)}</b></a>`, meta, resume, flags, verdict, mine, sent, FINAL[r.status] ?? '']
    .filter(Boolean)
    .join('\n');
}
// Общий код робота-отклика (этап 6, docs/stages/stage-6.md): W3, W5, W6, W7, W9.
// Подключается строкой «// @include n8n/shared/robot.js» после n8n/shared/time.js и n8n/shared/card.js (нужны TZ,
// localDate, localTime и esc).

const VNC_URL = 'vnc://localhost:5901';

// Можно ли откликнуться роботом: ✅ с письмом, без теста работодателя и не на сайте работодателя, не в очереди.
// enabled — настройка apply.enabled (W3 её не читает: выключенного робота поймает W9 при нажатии)
const robotEligible = (r, enabled = true) =>
  Boolean(enabled && r?.status === 'approved' && r.letter && !r.has_test && r.apply_type !== 'external' && !r.apply_state);

// Каким резюме hh откликаться (несколько резюме, docs/resumes.md): резюме вакансии — resume_id (пусто — основное).
// Нужен n8n/shared/resumes.js. → { ok: true, resume: { hash, title } } — резюме связано с резюме на hh, робот выберет его
// в окне отклика; { ok: true, resume: null } — основное не связано: робот откликнется резюме по умолчанию (как раньше);
// { ok: false, reason } — роботом откликаться нельзя, откликнулось бы не тем резюме: другое резюме не связано с hh или
// основное не связано, а с hh связано другое резюме (на hh их несколько, и по умолчанию может уйти не то)
function robotResume(s, row) {
  const id = row?.resume_id && resumeById(s, row.resume_id) ? row.resume_id : 'r1';
  const r = resumeById(s, id);
  if (r?.hh?.hash) return { ok: true, resume: { hash: r.hh.hash, title: r.hh.title } };
  if (id === 'r1') {
    if (!resumeList(s).some((x) => x.id !== 'r1' && x.hh?.hash)) return { ok: true, resume: null };
    return {
      ok: false,
      reason: `основное резюме «${r?.name ?? 'Основное'}» не связано с резюме на hh, а робот откликнулся бы резюме hh по умолчанию: свяжите его (⚙️ → 📄 Резюме → 📥 Импорт с hh → 🔗 Это основное) или откликнитесь вручную`,
    };
  }
  return {
    ok: false,
    reason: `резюме «${r?.name ?? id}» не связано с резюме на hh: импортируйте его (⚙️ → 📄 Резюме → 📥 Импорт с hh) или откликнитесь вручную`,
  };
}

// Подпись 🚀 под письмом: при нескольких резюме — каким резюме откликнется робот (resume_name вакансии, пишет W1).
// Пусто — прежняя подпись: её подставляет сама кнопка (scripts/build-workflows.mjs → robotLetterButtons)
const robotButtonText = (r) => {
  const name = String(r?.resume_name ?? '').trim();
  return name ? `🚀 Роботом: ${name.length > 40 ? `${name.slice(0, 39)}…` : name}` : '';
};

// «День» робота для лимита — с 09:00 по местному (решение пользователя 10.10.2026): отложенные на завтра отклики
// уходят, когда тихие часы (23–09) закончились
const robotDayStart = (now = Date.now(), tz = TZ) => localDayStart(now, tz, 9);
// Живые отклики робота за текущий «день»
const robotToday = (rows, now = Date.now()) =>
  rows.filter((r) => r.apply_by === 'robot' && Date.parse(r.applied_at) >= robotDayStart(now)).length;

// Темп всех откликов робота (6.1c, 20.10.2026; по умолчанию — «как руками», решение пользователя): пауза между
// попытками [min, max] секунд и откликов в час. W9 шлёт его в POST /apply, держит сам робот (applier/src/pace.mjs)
const PACE = {
  human: { name: 'как руками', min: 20, max: 60, hour: 30 },
  normal: { name: 'обычный', min: 45, max: 120, hour: 15 },
  careful: { name: 'осторожный', min: 120, max: 300, hour: 8 },
};
const robotPace = (s) => PACE[s['apply.pace']] ?? PACE.human;
// '20–60 с', '2–5 мин'
const paceGap = (p) => (p.min >= 120 ? `${p.min / 60}–${p.max / 60} мин` : `${p.min}–${p.max} с`);

// Как ушло письмо — в строку «🚀 Отправлено»
const LETTER_HOW = { attached: ' · ✉️ письмо приложено', chat: ' · 💬 письмо — в чате отклика', none: ' · ⚠️ без письма' };

// Строка робота в сообщении с письмом: очередь, итог, пометка. r — строка вакансии
// (+ robot_wait — чего ждёт робот: «капчу hh», «вход в hh»…)
function robotLine(r) {
  // Автоотклик (6.1c): вакансию в очередь поставил робот сам, не 🚀
  const auto = r.apply_mode === 'auto';
  if (r.apply_state === 'queued' || r.apply_state === 'applying') {
    if (r.robot_wait) return `⏸ Робот ждёт: ${esc(r.robot_wait)}`;
    return auto ? '⏳ 🤖 Автоотклик: робот откликнется сам — ⛔ чтобы не откликаться' : '⏳ Робот откликается…';
  }
  if (r.status === 'applied' && r.apply_by === 'robot') {
    // Несколько резюме: каким резюме ушёл отклик (робот сверяет это на hh, иначе — пометка в apply_note)
    const resume = r.resume_name ? ` резюме «${esc(r.resume_name)}»` : '';
    return `🚀 Отправлено${auto ? ' 🤖 автооткликом' : ''} ${localDate(r.applied_at)} ${localTime(r.applied_at)}${resume}${LETTER_HOW[r.apply_letter] ?? ''}${
      r.apply_note ? `\n⚠️ hh: ${esc(r.apply_note)}` : ''
    }`;
  }
  if (r.status === 'applied' && r.apply_by === 'hh') return '📨 Отклик уже был на hh — отметил';
  if (r.status !== 'approved') return '';
  const note = r.apply_note ? `: ${esc(r.apply_note)}` : '';
  const lines = {
    test: '🧩 У вакансии вопросы работодателя — откликнитесь сами',
    external: '🌐 Отклик на сайте работодателя — откликнитесь сами',
    // Скрыто конкретное резюме (несколько резюме, этап 5): робот называет его в заметке
    hidden: `🙈 ${/^резюме/.test(r.apply_note ?? '') ? esc(r.apply_note) : 'hh просит открыть резюме этому работодателю'} — откликнитесь сами`,
    error: `⚠️ Робот не смог${note}${(r.apply_tries ?? 0) >= 3 ? ' — третий раз, откликнитесь сами' : ''}`,
    dry_run: `🧪 Сухой прогон (APPLY_LIVE=0), отклик не отправлен${note}`,
    disabled: '⏸ Робот выключен (⚙️ → 🚀 Робот) — откликнитесь сами',
    no_resume: `📄 Робот не откликается: ${esc(r.apply_note || 'резюме не связано с резюме на hh')}`,
    // ⛔ (6.1c): автоотклик эту вакансию больше не возьмёт, откликнуться можно 🚀 или вручную
    stopped: '⛔ Убрал из очереди робота — автоотклик её не возьмёт',
  };
  return lines[r.apply_result] ?? '';
}
// Общий код сообщения с письмом в Telegram: W5 «Format letter», W3 «Apply sent», W9 Robot.
// Подключается после n8n/shared/card.js (нужны esc и thaiDate) и n8n/shared/robot.js (строка робота):
//   // @include n8n/shared/card.js
//   // @include n8n/shared/robot.js
//   // @include n8n/shared/letter.js

const LETTER_HEAD = { new: '✉️ Письмо', redo: '🔄 Новый вариант письма', revise: '✏️ Письмо с правкой' };
// Нейросеть повторилась (W5 «Parse letter», same; 14.10.2026): письмо всё равно отправлено — на него можно ответить правкой
const LETTER_SAME = {
  revise: '⚠️ Нейросеть не поменяла письмо. Напиши пожелание иначе: что убрать или на что заменить.',
  redo: '⚠️ Вариант почти как прошлый — нажми «🔄 Переписать» ещё раз.',
};

// r: строка вакансии + { ok, letter, problem, mode, instruction, same }. Письмо — в <pre>: копируется одним нажатием.
// После «📨 Отправил» (status = applied) подсказки заменяет строка «📨 Отклик отправлен …».
// Под письмом с правкой — куда записать факт о себе для всех писем (пожелание живёт только в письмах этой вакансии)
// Робот (этап 6): строку очереди и итога даёт robotLine из n8n/shared/robot.js (подключается перед этим файлом)
// Несколько резюме: последняя строка, прямо над кнопками, — каким резюме отклик (письмо написано по нему, им откликнется
// робот, его выбрать на hh вручную), пока отклик не отправлен; после отклика роботом резюме называет строка «🚀 Отправлено»
// Модель (19.10.2026, решение пользователя: «всегда мелко») — в конце шапки, из колонки letter_model (modelLabel —
// n8n/shared/card.js); fallback — только сразу после W5: Claude по подписке не смог, письмо написал запасной Gemini
function letterText(r) {
  const model = r.letter_model ? ` · <i>${esc(modelLabel(r.letter_model))}</i>` : '';
  const head = `${LETTER_HEAD[r.mode] ?? LETTER_HEAD.new} · <a href="${r.url}">${esc(r.title)}</a> · ${esc(r.company)}${model}`;
  if (!r.ok) {
    return [head, `⚠️ Письмо не получилось: ${esc(r.problem)}`, 'Нажми «🔄 Переписать», чтобы попробовать ещё раз.'].join('\n');
  }
  const sent = r.status === 'applied';
  const closed = r.status === 'archived';
  const robot = typeof robotLine === 'function' ? robotLine(r) : '';
  return [
    head,
    r.fallback ? `⚠️ Claude по подписке: ${esc(r.fallback.note)} — письмо написал Gemini.` : '',
    r.mode === 'revise' && r.instruction ? `<i>Пожелание: «${esc(r.instruction)}»</i>` : '',
    LETTER_SAME[r.same] ?? '',
    `<pre>${esc(r.letter)}</pre>`,
    // Робот включён, но вакансия ему не подходит (W5 «Format letter») — почему нет 🚀
    !sent && !closed && r.robot_hint ? `🤖 Робот не откликается: ${esc(r.robot_hint)}` : '',
    !sent && !closed && r.has_test && r.apply_result !== 'test' && !r.robot_hint ? '📝 У вакансии тест — ответы в форме отклика на hh.' : '',
    sent
      ? robot || `📨 Отклик отправлен${r.applied_at ? ` ${localDate(r.applied_at)}` : ''}`
      : closed
        ? '🔒 Вакансия закрыта на hh — отклик уже не отправить'
        : robot || '<i>Нажми на письмо — скопируется. Поправить — ответь на это сообщение.</i>',
    !sent && !closed && r.mode === 'revise' ? '<i>Факт о себе для всех писем — ⚙️ → 👤 Профиль → ➕ Дополнительно к резюме.</i>' : '',
    !sent && !closed && r.resume_name ? `📄 Отклик резюме «${esc(r.resume_name)}»` : '',
  ]
    .filter(Boolean)
    .join('\n');
}

const action = $('Route').first().json;
// Строка — из «Sent row» по имени: вход этой ноды может смениться при правках workflow
const row = $('Sent row').first().json;
// Робот (этап 6) отправляет отклик с этим письмом — кнопки письма не трогаем
const busy = Boolean(row.apply_state);
const sent = !busy && action.op === 'sent';
const updated = busy
  ? row
  : {
      ...row,
      status: sent ? 'applied' : 'approved',
      applied_at: sent ? row.applied_at || new Date().toISOString() : '',
      apply_by: sent ? 'me' : '',
    };

return [
  {
    json: {
      id: row.id,
      sent,
      busy,
      status: updated.status,
      applied_at: updated.applied_at ?? '',
      apply_by: updated.apply_by ?? '',
      // «↩️ Отменить»: письму возвращаются кнопки — с 🚀, если вакансия подходит роботу
      robot: robotEligible({ ...updated, apply_state: '' }),
      robot_button: robotButtonText(updated),
      letterText: letterText({ ...updated, ok: Boolean(row.letter), problem: 'письма нет', mode: 'new' }),
      cardText: cardText(updated),
      chatId: action.chatId,
      letterMessageId: action.messageId,
      cardId: row.tg_message_id,
      queryId: action.queryId,
      toast: busy
        ? '🚀 Робот в работе — сначала ⛔ под письмом'
        : sent
          ? '📨 Записал: отклик отправлен'
          : '↩️ Отменил: отклик не отправлен',
      apply_url: row.apply_url,
      url: row.url,
    },
  },
];

// W3 · Apply cancel — «↩️ Отменить отклик» под письмом (решение пользователя 14.10.2026): вакансия снова ждёт решения.
// Нода: Code, режим «Run Once for All Items».
// Вход: строка вакансии из «Sent row», кнопка — из «Route» (op = cancel; messageId — сообщение с письмом).
// Выход: { id, ok, toast, queryId, chatId, cardId, cardText, letterMessageId, letterText, deleteIds }
//   ok — «Save cancel»: status = waiting, решение и причина сброшены, письмо забыто (✅ снова — новое письмо),
//        3 дня до «⌛ устарела» — заново. Карточке — кнопки выбора («Card: reset»); письмо — без кнопок («Letter: cancelled»),
//        потом удаляется вместе с текущим письмом строки и «Почему?» без ответа (deleteIds). Старше 48 ч Telegram
//        удалить не даст — останется письмо без кнопок.
//   ok = false — только тост: робот в работе (этап 6), письмо ещё пишется (letter_lock моложе 3 мин — как «Unlock stale»),
//        отклик отправлен или вакансия закрыта.

// Время человека (13.10.2026, docs/onboarding.md): часовой пояс — настройка profile.tz (IANA, например Asia/Bangkok),
// иначе пояс компьютера (USER_TZ из .env — его пишет мастер установки), иначе Москва. Расписание сбора по-прежнему
// считается по Москве (n8n/shared/schedule.js): hh публикует вакансии по МСК.
// Общий код: строка «// @include n8n/shared/time.js» — раньше n8n/shared/card.js и n8n/shared/robot.js (им нужен TZ).
// Пояс берётся из ноды «Settings», если она есть в workflow и уже выполнилась; без неё — USER_TZ.

const MSK_TZ = 'Europe/Moscow';
const validTz = (tz) => {
  try {
    return Boolean(tz) && Boolean(new Intl.DateTimeFormat('en-GB', { timeZone: tz }));
  } catch {
    return false;
  }
};

// Пояс этого запуска
function currentTz() {
  let tz = '';
  try {
    const row = $('Settings')
      .all()
      .map((i) => i.json)
      .find((r) => r?.name === 'profile.tz');
    tz = row ? JSON.parse(row.value_json) : '';
  } catch {
    // в workflow нет ноды «Settings» или строка битая — пояс компьютера
  }
  const env = typeof $env === 'undefined' ? '' : $env.USER_TZ;
  return [tz, env, MSK_TZ].find(validTz);
}
const TZ = currentTz();

// Части даты в поясе tz числами: { y, mo, d, h, mi }
function zonedParts(ms, tz = TZ) {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  }).formatToParts(new Date(ms));
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  return { y: get('year'), mo: get('month'), d: get('day'), h: get('hour'), mi: get('minute') };
}
const pad2 = (n) => String(n).padStart(2, '0');

// 1760340720000 → '14:32'
const localHM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.h)}:${pad2(p.mi)}`;
};
// → '07.10'
const localDM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.d)}.${pad2(p.mo)}`;
};
// → '2026-10-07' — ключ дня
const localDay = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${p.y}-${pad2(p.mo)}-${pad2(p.d)}`;
};
const localHour = (ms, tz = TZ) => zonedParts(ms, tz).h;

// Смещение пояса от UTC в минутах в момент ms (Бангкок: +420)
function tzOffsetMin(ms, tz = TZ) {
  const p = zonedParts(ms, tz);
  return Math.round((Date.UTC(p.y, p.mo - 1, p.d, p.h, p.mi) - Math.floor(ms / 60000) * 60000) / 60000);
}

// 'UTC+7', 'UTC+5:30', 'UTC−4'
function tzLabel(tz = TZ, ms = Date.now()) {
  const off = tzOffsetMin(ms, tz);
  const abs = Math.abs(off);
  return `UTC${off < 0 ? '−' : '+'}${Math.floor(abs / 60)}${abs % 60 ? `:${pad2(abs % 60)}` : ''}`;
}

// Начало «дня», который начинается в hour:00 по местному: последний такой момент не позже ms
function localDayStart(ms, tz = TZ, hour = 0) {
  const p = zonedParts(ms, tz);
  let start = Date.UTC(p.y, p.mo - 1, p.d, hour) - tzOffsetMin(ms, tz) * 60000;
  if (start > ms) start -= 24 * 3600 * 1000;
  return start;
}

// Тихие часы 23:00–09:00 по местному: карточки и сводка — без звука, тревоги — со звуком
const quietHours = (ms = Date.now(), tz = TZ) => {
  const h = localHour(ms, tz);
  return h >= 23 || h < 9;
};

// Время по местному и в скобках по Москве: '14:32 (10:32 МСК)'; пояс совпадает с Москвой — '10:32 МСК'
const localMsk = (ms, tz = TZ) =>
  tzOffsetMin(ms, tz) === tzOffsetMin(ms, MSK_TZ) ? `${localHM(ms, MSK_TZ)} МСК` : `${localHM(ms, tz)} (${localHM(ms, MSK_TZ)} МСК)`;

// Момент ISO (applied_at) → дата и время по местному: '2026-10-06T21:17:55Z' → '07.10', '04:17'
const localDate = (iso) => (Date.parse(iso) ? localDM(Date.parse(iso)) : '');
const localTime = (iso) => (Date.parse(iso) ? localHM(Date.parse(iso)) : '');

// Общий код карточки вакансии в Telegram: W2 «Format card» и W3 «Apply choice».
// В Code-ноду попадает при сборке: строка «// @include n8n/shared/card.js» заменяется этим файлом
// (scripts/build-workflows.mjs, scripts/run-code-node.mjs). Раньше него — n8n/shared/time.js (localDate).

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const EXPERIENCE = { noExperience: 'без опыта', between1And3: '1–3 г.', between3And6: '3–6 л.', moreThan6: '6+ л.' };
const CURRENCY = { RUR: '₽', USD: '$', EUR: '€', KZT: '₸', BYR: 'Br', UZS: 'сум' };

// Решение нейросети (колонка decision)
const VERDICT = { apply: '🟢 apply', maybe: '🟡 maybe', skip: '🔴 skip', error: '⚠️ не оценено' };
// Подписи моделей нейросети (19.10.2026, docs/claude-cli.md): шапка письма (letter_model) и кнопки ⚙️ → 🤖
const MODEL_LABELS = {
  'claude-haiku-5-5': 'Haiku 5.5',
  'claude-sonnet-5-5': 'Sonnet 5.5',
  'claude-opus-5-5': 'Opus 5.5',
  'claude-haiku-4-5': 'Haiku 4.5',
};
// 'gemini-3.5-flash-lite' → 'Gemini 3.5 Flash-Lite'; неизвестная модель — как есть
function modelLabel(id) {
  const name = String(id ?? '');
  if (MODEL_LABELS[name]) return MODEL_LABELS[name];
  if (!name.startsWith('gemini-')) return name;
  const words = name.slice(7).split('-').map((w) => w.charAt(0).toUpperCase() + w.slice(1));
  return `Gemini ${words.join('-')}`.replace(/(\d)-/, '$1 ');
}
// Кнопки пользователя: callback_data = v:<id строки>:<choice>, решение — в колонку my_decision.
// earlier — «📨 Уже откликался» (до бота, 07.10.2026): status = applied без письма и без applied_at,
// без «Почему?» и вне теневого режима (сравниваются только apply / maybe / skip)
const CHOICE = { apply: '✅ Откликнусь', maybe: '🤔 Возможно', skip: '❌ Мимо', earlier: '📨 Откликался раньше' };
// «🚫 В ЧС» на карточке (07.10.2026): компания уходит в чёрный список, вакансия — ❌ с этой причиной
const BAN_REASON = 'чёрный список';
const STATUS_BY_CHOICE = { apply: 'approved', maybe: 'maybe', skip: 'skipped', earlier: 'applied' };

const short = (n) => (n >= 1000 ? `${Math.round(n / 1000)}k` : String(n));

function salary(r) {
  if (!r.salary_from && !r.salary_to) return '';
  const range =
    r.salary_from && r.salary_to
      ? `${short(r.salary_from)}–${short(r.salary_to)}`
      : r.salary_from
        ? `от ${short(r.salary_from)}`
        : `до ${short(r.salary_to)}`;
  return `💰 ${range} ${CURRENCY[r.currency] ?? r.currency ?? ''}${r.salary_gross ? ' до налогов' : ''}`;
}

// «Москва, Сербия, Грузия, Армения» → «Москва, Сербия +2»
function areas(s) {
  const list = String(s ?? '').split(', ').filter(Boolean);
  return list.length > 2 ? `${list.slice(0, 2).join(', ')} +${list.length - 2}` : list.join(', ');
}

// '2026-10-06T13:22:00+0300' → '06.10'
function published(s) {
  const m = String(s ?? '').match(/^\d{4}-(\d{2})-(\d{2})/);
  return m ? `${m[2]}.${m[1]}` : '';
}

// Итоговые состояния без кнопок: W3 «📨 Отправил», W6 «⌛ устарела» и «🔒 закрыта на hh»
const FINAL = { expired: '⌛ Устарела: 3 дня без решения', archived: '🔒 Вакансия закрыта на hh' };

// Текст карточки (Parse Mode = HTML). Строка «👤 …» появляется после нажатия кнопки,
// «📨 …» — после «Отправил» под письмом (W3, status = applied), FINAL — после W6
function cardText(r) {
  const date = published(r.published_at);
  const meta = [esc(r.company), salary(r), EXPERIENCE[r.experience] ?? '', esc(areas(r.areas)), date && `📅 ${date}`]
    .filter(Boolean)
    .join(' · ');
  const flags = [
    r.has_test && '📝 тест',
    r.letter_required && '✉️ письмо обязательно',
    r.responses != null && `👥 ${r.responses}`,
    r.error && `⚠️ ${esc(r.error)}`,
  ]
    .filter(Boolean)
    .join(' · ');
  // Нейросеть не оценивала, а фильтр отсеял (в том числе вакансия, возвращённая с панели меню, 08.10.2026) — причины фильтра
  const verdict =
    !r.decision && r.reasons
      ? `🧹 Отсеяна фильтром: ${esc(r.reasons)}`
      : `🤖 ${VERDICT[r.decision] ?? esc(r.decision)}${r.llm_reason ? ` — ${esc(r.llm_reason)}` : ''}`;
  // Автоотклик (6.1c): решение за пользователя принял робот по apply нейросети — вместо строки «👤 …»
  const mine = CHOICE[r.my_decision]
    ? `👤 ${CHOICE[r.my_decision]}${r.my_reason === BAN_REASON ? ' · 🚫 компания в чёрном списке' : ''}`
    : r.apply_mode === 'auto' && ['approved', 'applied'].includes(r.status)
      ? '🤖 Автоотклик'
      : '';
  // «📨 Откликался раньше» уже в строке «👤 …» — второй раз не пишем
  // Робот (этап 6): «🚀 … роботом»; нашёлся на hh без «📨 Отправил» (6.2) — «📨 … на hh»
  const who = r.apply_by === 'robot' ? '🚀 Отклик отправлен роботом' : r.apply_by === 'hh' ? '📨 Отклик есть на hh' : '📨 Отклик отправлен';
  const sent =
    r.status === 'applied' && r.my_decision !== 'earlier' ? `${who}${r.applied_at ? ` ${localDate(r.applied_at)}` : ''}` : '';
  // Несколько резюме (docs/resumes.md): каким резюме вакансия. resume_name пишет W1 всем вакансиям, пока резюме
  // больше одного (у основного resume_id пустой), и обновляет W11 при переименовании и удалении резюме
  const resume = r.resume_name ? `📄 Резюме: ${esc(r.resume_name)}` : '';
  return [`<a href="${r.url}"><b>${esc(r.title)}</b></a>`, meta, resume, flags, verdict, mine, sent, FINAL[r.status] ?? '']
    .filter(Boolean)
    .join('\n');
}

const action = $('Route').first().json;
// Строка — из «Sent row» по имени (как в «Apply sent»): одна нода Get на кнопки письма, кроме «🔄»
const row = $('Sent row').first().json;

const writing = Boolean(row.letter_lock) && Date.now() - Date.parse(row.letter_lock) < 3 * 60 * 1000;
const refusal = row.apply_state
  ? '🚀 Робот в работе — сначала ⛔ под письмом'
  : writing
    ? '✍️ Письмо ещё пишется — отмени, когда придёт'
    : row.status === 'applied'
      ? row.apply_by === 'me'
        ? '📨 Уже отмечено «Отправил» — сначала «↩️ Отменить»'
        : '📨 Отклик уже отправлен'
      : (FINAL[row.status] ?? '');

return [
  {
    json: {
      id: row.id,
      ok: !refusal,
      toast: refusal || '↩️ Отклик отменён — вакансия снова ждёт решения',
      queryId: action.queryId,
      chatId: action.chatId,
      cardId: row.tg_message_id,
      cardText: cardText({ ...row, status: 'waiting', my_decision: '', my_reason: '' }),
      letterMessageId: action.messageId,
      letterText: [
        `↩️ Отклик отменён · <a href="${row.url}">${esc(row.title)}</a> · ${esc(row.company)}`,
        'Вакансия снова ждёт решения — кнопки на карточке.',
      ].join('\n'),
      // Удалить: письмо, где нажали; текущее письмо строки (если нажали на старом); «Почему?» без ответа
      deleteIds: [...new Set([action.messageId, row.tg_letter_id, row.my_reason ? 0 : row.tg_ask_id].map(Number))].filter(Boolean),
    },
  },
];

// W3 · Cancel ids — что удалить после «↩️ Отменить отклик»: письмо, текущее письмо строки и «Почему?» без ответа.
// Нода: Code, режим «Run Once for All Items». Вход: «Apply cancel» → deleteIds.
// Выход: item на сообщение { messageId } → «Delete cancelled» (onError = continue: старше 48 ч Telegram удалить не даёт).
return ($('Apply cancel').first().json.deleteIds ?? []).map((messageId) => ({ json: { messageId } }));

// W3 · Sync job — обновить панель меню (W7 Bot menu), если на ней открыта эта вакансия:
//   решение на карточке в ленте («Apply choice», не из панели), «📨 Отправил» / «↩️ Отменить» под письмом
//   («Apply sent») или «↩️ Отменить отклик» («Apply cancel») — кнопки решения на панели должны совпадать с карточкой в ленте.
// Нода: Code, режим «Run Once for All Items». Открыта другая вакансия или список — W7 ничего не делает.
// Выход: { action: 'panel', view: 'sync', id, choose, … } → «Panel sync» (Execute Workflow, без ожидания).

const from = (name) => {
  try {
    return $(name).first().json;
  } catch {
    return null; // нода не выполнялась в этом запуске
  }
};
const cancel = from('Apply cancel');
const sent = cancel ? null : from('Apply sent');
const choice = cancel || sent ? null : from('Apply choice');
const s = cancel ?? sent ?? choice;

return [
  {
    json: {
      action: 'panel',
      view: 'sync',
      id: s.id,
      chatId: s.chatId,
      tab: '',
      page: 1,
      queryId: '',
      messageId: 0,
      userMessageId: 0,
      // «↩️ Изменить» на карточке в ленте — на панели тоже кнопки выбора
      choose: choice?.keyboard === 'choose',
    },
  },
];

// W3 · Reply kind — на что ответил пользователь: на письмо (правка) или на карточку / «почему?» (причина).
// Нода: Code, режим «Run Once for All Items».
// Вход: строка вакансии из «Reply row» (найдена по tg_letter_id, tg_ask_id или tg_message_id = replyTo),
//       сам ответ — из «Route».
// Выход: { id, kind: revise | busy | reason, text }

const reply = $('Route').first().json;
const row = $input.first().json;
return [
  {
    json: {
      id: row.id,
      // Правка письма, пока робот отправляет его (этап 6), не применяется — busy
      kind: row.tg_letter_id === reply.replyTo ? (row.apply_state ? 'busy' : 'revise') : 'reason',
      text: reply.text,
    },
  },
];

// W3 · Panel job — перерисовать панель меню (W7 Bot menu) после решения, принятого в карточке на панели.
// Нода: Code, режим «Run Once for All Items». Выполняется последней: исходная карточка уже перерисована,
// «Почему?» и письмо запущены, строка в таблице записана.
// Выход: задание для W7 { action: 'panel', view: 'open', … } → «Panel refresh» (Execute Workflow, без ожидания).
//   choose = true — нажали «↩️ Изменить»: на панели снова кнопки выбора, хотя решение в строке осталось.

const c = $('Apply choice').first().json;

return [
  {
    json: {
      action: 'panel',
      view: 'open',
      id: c.id,
      tab: c.panel.tab,
      page: c.panel.page,
      chatId: c.chatId,
      messageId: c.panel.messageId,
      userMessageId: 0,
      queryId: '',
      choose: c.keyboard === 'choose',
    },
  },
];

// W3 · Letter job — задание для W5 Letter: { id, letter_mode, instruction, replace }.
// Нода: Code, режим «Run Once for All Items». В неё ведут три ветки — в запуске работает одна:
//   ✅ на карточке и письма ещё нет («Apply choice», need_letter) → new;
//   «🔄 Переписать» под письмом («Route», action = letter) → redo;
//   ответ на письмо («Reply kind», kind = revise) → revise, instruction — текст ответа.
// replace — что удалить, когда новое письмо придёт (решение пользователя 07.10.2026: в ленте только актуальное):
//   redo — сообщение, где нажали «🔄» (письмо или «⚠️ Письмо не получилось»);
//   revise — письмо, на которое ответили, и сам ответ с пожеланием (оно видно в новом письме).
//   Прошлое письмо из строки (tg_letter_id) W5 удаляет и так.

const from = (name) => {
  try {
    return $(name).first().json;
  } catch {
    return null; // нода не выполнялась в этом запуске
  }
};
const reply = from('Reply kind');
const route = from('Route');
const choice = from('Apply choice');

if (reply?.kind === 'revise') {
  return [
    {
      json: {
        id: reply.id,
        letter_mode: 'revise',
        instruction: reply.text,
        replace: [route?.replyTo, route?.messageId].filter(Boolean),
      },
    },
  ];
}
if (route?.action === 'letter') {
  return [{ json: { id: route.id, letter_mode: 'redo', instruction: '', replace: [route.messageId].filter(Boolean) } }];
}
if (choice?.need_letter) return [{ json: { id: choice.id, letter_mode: 'new', instruction: '', replace: [] } }];
return [];

// W3 · Locked job — письмо уже пишется: второе нажатие ✅ или «🔄» не должно запустить второй W5 (07.10.2026).
// Нода: Code, режим «Run Once for All Items». Вход: «Letter lock» — строка, если захват удался (letter_lock был пуст);
// пустой выход «Letter lock» — письмо уже пишется, эта нода не выполняется и W5 не вызывается.
// Выход: задание из «Letter job» → «Write letter». W5 снимает letter_lock в конце (нода «Unlock»).

return [$('Letter job').first()];
